import { test, expect } from '@playwright/test';

test.describe('Mobile Modal Full-Screen on Small Viewports', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal');
  });

  test('should display modal in full-screen on small viewports', async ({ page }) => {
    // Set viewport to mobile size
    await page.setViewportSize({ width: 375, height: 667 });

    // Verify modal is visible and covers the entire screen
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();
    await expect(modal).toHaveAttribute('aria-label', 'Modal');

    const modalContent = page.getByRole('main');
    await expect(modalContent).toBeVisible();

    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify modal is full-screen
    const modalRect = await modal.boundingBox();
    expect(modalRect.width).toBeGreaterThan(375);
    expect(modalRect.height).toBeGreaterThan(667);

    // Verify modal content is visible and not cut off
    await expect(modalContent).toBeVisible();
    await expect(modalContent).toBeVisible();

    // Verify close button is visible and functional
    await expect(closeButton).toBeVisible();
    await closeButton.click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();
  });

  test('should handle modal closing on small viewports', async ({ page }) => {
    // Set viewport to mobile size
    await page.setViewportSize({ width: 375, height: 667 });

    // Open modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is open
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify modal content is visible and not cut off
    const modalContent = page.getByRole('main');
    await expect(modalContent).toBeVisible();

    // Verify close button is visible and functional
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Close modal
    await closeButton.click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();

    // Verify page content is visible
    const pageContent = page.getByRole('main');
    await expect(pageContent).toBeVisible();
  });
});
